struct Payload =>
  bytes: byte[]

fn hex(bytes: byte[]): str =>
  return bytes.toHex()

fn main(): void =>
  var bytes: byte[] = {1b, 2b, 255b}
  println(hex(bytes))
  var encode: fn(byte[]): str = fn(value: byte[]): str => value.toBase64()
  println(encode(bytes))
  var payload: Payload = { bytes: {65b, 233b} }
  println(payload.bytes.toStringLatin1())
  sync var shared: byte[] = {77b, 97b, 110b}
  var captured: fn(): str = fn(): str => shared.toHex()
  println(captured())

fn main(): void =>
  sync var bytes: byte[] = {77b, 97b, 110b}
  var first: fn(): str = fn(): str => bytes.toHex()
  var outer: fn(): str = fn(): str =>
    var inner: fn(): str = fn(): str => bytes.toHex()
    return inner()
  bytes[0] = 66b
  println(first())
  println(outer())
  println(bytes.toHex())
  var second: fn(): str = fn(): str => bytes.toHex()
  println(second())
  var mutate: fn(): str = fn(): str =>
    bytes[0] = 67b
    return bytes.toHex()
  println(mutate())
  println(mutate())
  println(bytes.toHex())

